"""Stop-hook loop continuation engine (Loop Engineering P2, epic #75).

Converts Synaptory's prompt-driven delivery loop into a harness-enforced
one. When Claude stops mid-execution with dispatchable work remaining and no
human gate pending, the Stop hook (synaptory-loop-continue.sh) returns
``{"decision":"block","reason": …}`` so the session keeps driving the story
pipeline instead of trusting the model to remember to.

All decision logic lives here (pure enough to unit-test against a fixture
project dir); the shell hook is a thin adapter. `should_continue` OWNS two
side effects — the runaway-guard state file and events.jsonl breadcrumbs —
both file-only so tests exercise them via tmp dirs. Control-plane telemetry
(the CLI `telemetry activity` call) is NOT fired here: `should_continue`
returns an ``activity`` descriptor and the shell hook ships it best-effort,
so a missing CLI can never affect the decision.

GOVERNANCE (non-negotiable, epic #75): this engine continues ONLY on
dispatchable agent work in structured mode during an execution lifecycle
state. It never continues past a human gate — `await_acceptance`,
interactive mode, review/close lifecycle states, or an exhausted board all
allow the session to stop. Kill switches: env ``SYNAPTORY_LOOP_DISABLE=1``
and config ``resilience.loop_continuation: disabled``.
"""

from __future__ import annotations

import os
from pathlib import Path
from typing import Any

# story_pipeline and the state machines live in this same dir; the shell hook
# runs us with the dir on sys.path.
from story_pipeline import CONTINUE_ELIGIBLE, progress_digest

LOOP_DISABLE_ENV = "SYNAPTORY_LOOP_DISABLE"
DEFAULT_NO_PROGRESS_CAP = 2
# Belt-and-suspenders ceiling independent of the progress hash: even if the
# board keeps changing every stop, refuse to drive a single session forever.
ABSOLUTE_CONTINUATION_CAP = 50

# Actions from the lifecycle-aware wrappers that MUST let the session stop.
# (CONTINUE_ELIGIBLE from story_pipeline is the complement.) Listed for the
# reason strings / tests; membership is decided by CONTINUE_ELIGIBLE.
STOP_ACTIONS = (
    "await_acceptance",
    "sprint_complete",
    "await_sync",  # SPQ cross-workstream barrier — a human gate (§8, §10.2)
    "all_blocked",
    "no_stories",
    "not_in_execution",
)


def _guard_path(project_dir: str) -> Path:
    return Path(project_dir) / ".synaptory" / ".orchestrator" / "loop-guard.json"


def _read_guard(project_dir: str) -> dict[str, Any]:
    import json

    try:
        return json.loads(_guard_path(project_dir).read_text(encoding="utf-8"))
    except (OSError, ValueError):
        return {}


def _write_guard(project_dir: str, guard: dict[str, Any]) -> None:
    import json

    p = _guard_path(project_dir)
    try:
        p.parent.mkdir(parents=True, exist_ok=True)
        p.write_text(json.dumps(guard, separators=(",", ":")), encoding="utf-8")
    except OSError:
        pass  # guard persistence is best-effort; a lost write just re-evaluates next stop


def _config_disabled(project_dir: str) -> bool:
    """True when `.synaptory.yaml` sets `resilience.loop_continuation: disabled`
    (or false/off/no). Absent key → not disabled (loop-continuation is on by
    default in structured mode)."""
    cfg = Path(project_dir) / ".synaptory.yaml"
    try:
        text = cfg.read_text(encoding="utf-8")
    except OSError:
        return False
    in_resilience = False
    for raw in text.splitlines():
        line = raw.split("#", 1)[0].rstrip()
        if not line:
            continue
        indent = len(line) - len(line.lstrip())
        s = line.strip()
        if indent == 0:
            in_resilience = s.startswith("resilience:")
            continue
        if in_resilience and s.startswith("loop_continuation:"):
            val = s.split(":", 1)[1].strip().strip('"').strip("'").lower()
            return val in ("disabled", "false", "off", "no", "0")
    return False


def _no_progress_cap(project_dir: str) -> int:
    cfg = Path(project_dir) / ".synaptory.yaml"
    try:
        text = cfg.read_text(encoding="utf-8")
    except OSError:
        return DEFAULT_NO_PROGRESS_CAP
    in_resilience = False
    for raw in text.splitlines():
        line = raw.split("#", 1)[0].rstrip()
        if not line:
            continue
        indent = len(line) - len(line.lstrip())
        s = line.strip()
        if indent == 0:
            in_resilience = s.startswith("resilience:")
            continue
        if in_resilience and s.startswith("loop_no_progress_cap:"):
            try:
                return max(1, int(s.split(":", 1)[1].strip()))
            except ValueError:
                return DEFAULT_NO_PROGRESS_CAP
    return DEFAULT_NO_PROGRESS_CAP


def _engagement_is_structured(project_dir: str) -> bool:
    try:
        from mode_reader import get_engagement_mode, normalize_mode

        return normalize_mode(get_engagement_mode(project_dir)) == "structured"
    except Exception:
        # Can't read the mode → fail SAFE toward stopping (never continue on
        # an unknown engagement mode).
        return False


def _lifecycle_next_action(project_dir: str) -> dict[str, Any] | None:
    """Read build_mode and delegate to the matching lifecycle-aware
    next_action wrapper. Returns None if state can't be read at all."""
    try:
        from spec_state import read_full_state

        full = read_full_state(project_dir)
    except Exception:
        return None
    if not full:
        return None
    build_mode = (full.get("build_mode") or "scrum").lower()
    try:
        # Explicit per-mode dispatch. This used to fall through to scrum for
        # ANY unrecognised build_mode, which meant a new lifecycle would
        # silently be driven by the WRONG state machine — fail-open, and
        # invisible. Unknown modes now refuse to drive the loop at all: the
        # caller treats None as "state unreadable" and lets the session stop,
        # which is the safe direction for a governance component.
        if build_mode == "kanban":
            import kanban_state_machine as sm
        elif build_mode == "spq":
            import spq_state_machine as sm
        elif build_mode == "scrum":
            import scrum_state_machine as sm
        else:
            return None
        na = sm.next_action(project_dir)
        if isinstance(na, dict):
            na["_build_mode"] = build_mode
        return na
    except Exception:
        return None


def _spec_state(project_dir: str) -> dict[str, Any]:
    """The active-spec story board next_action evaluated — same spec-aware
    read, so the progress digest matches what drove the decision."""
    try:
        from story_pipeline import _read_state

        return _read_state(project_dir)
    except Exception:
        return {"current_stories": []}


def _stop(reason_code: str, **extra: Any) -> dict[str, Any]:
    out = {"continue": False, "reason": None, "stop_reason": reason_code, "activity": None}
    out.update(extra)
    return out


def should_continue(project_dir: str, session_id: str) -> dict[str, Any]:
    """Decide whether the Stop hook should refuse to stop.

    Returns a dict:
      continue   : bool — True → hook emits decision:block
      reason     : str|None — the block reason (present iff continue)
      stop_reason: str — short code for why we stopped (telemetry/debug)
      activity   : {kind, summary}|None — a telemetry activity the shell hook
                   ships best-effort (loop_continue / loop_guard_trip)
    """
    from synaptory_logger import emit as _log_emit

    # Kill switches first (cheapest, and must always win).
    if os.environ.get(LOOP_DISABLE_ENV) == "1":
        return _stop("disabled_env")
    if _config_disabled(project_dir):
        return _stop("disabled_config")

    # Structured mode only — interactive mode is user-in-the-loop by design.
    if not _engagement_is_structured(project_dir):
        return _stop("not_structured")

    na = _lifecycle_next_action(project_dir)
    if na is None:
        # Missing/corrupt state → allow stop, leave a breadcrumb so a broken
        # loop hook is diagnosable rather than silent.
        _log_emit("loop_engine_state_unreadable", project_dir=project_dir, session_id=session_id)
        return _stop("state_unreadable")

    action = na.get("action", "")
    if action not in CONTINUE_ELIGIBLE:
        # not_in_execution / await_acceptance / sprint_complete / all_blocked /
        # no_stories — every human gate and terminal outcome lands here.
        return _stop("action_not_continue_eligible", action=action)

    # Runaway guard. Compare the story-board progress digest across stops.
    cap = _no_progress_cap(project_dir)
    digest = progress_digest(_spec_state(project_dir))
    guard = _read_guard(project_dir)
    if guard.get("session_id") != session_id:
        guard = {  # new session → fresh guard
            "session_id": session_id,
            "progress_hash": None,
            "no_progress_count": 0,
            "continuations_this_session": 0,
            "tripped": False,
        }
    if guard.get("tripped"):
        return _stop("guard_tripped")

    if guard.get("progress_hash") == digest:
        guard["no_progress_count"] = int(guard.get("no_progress_count", 0)) + 1
    else:
        guard["no_progress_count"] = 0
        guard["progress_hash"] = digest

    tripped = (
        guard["no_progress_count"] >= cap
        or int(guard.get("continuations_this_session", 0)) >= ABSOLUTE_CONTINUATION_CAP
    )
    if tripped:
        guard["tripped"] = True
        _write_guard(project_dir, guard)
        why = (
            f"no board progress across {guard['no_progress_count']} consecutive stops"
            if guard["no_progress_count"] >= cap
            else f"continuation cap ({ABSOLUTE_CONTINUATION_CAP}) reached"
        )
        _log_emit(
            "loop_guard_trip",
            project_dir=project_dir,
            session_id=session_id,
            reason=why,
            no_progress_count=guard["no_progress_count"],
            continuations=guard.get("continuations_this_session", 0),
        )
        return _stop(
            "guard_tripped",
            activity={
                "kind": "loop_guard_trip",
                "summary": f"loop guard tripped — {why}; letting the session stop",
            },
        )

    # Continue.
    guard["continuations_this_session"] = int(guard.get("continuations_this_session", 0)) + 1
    _write_guard(project_dir, guard)

    sm_script = f"{na.get('_build_mode', 'scrum')}_state_machine.py"
    story_id = na.get("story_id") or "?"
    title = na.get("story_title")
    n = guard["continuations_this_session"]
    reason = (
        f"[synaptory loop] {na.get('lifecycle_state', '?')} — next action: "
        f"{action} for {story_id}"
        + (f" (\"{title}\")" if title else "")
        + f" — {na.get('reason', '')}. "
        f'Run `python3 "${{PLUGIN_ROOT}}/hooks/lib/{sm_script}" next_action "$(pwd)"` '
        "and execute the returned action. Do NOT stop until next_action returns "
        "sprint_complete, await_acceptance, await_sync, or all_blocked. "
        f"(continuation {n})"
    )
    _log_emit(
        "loop_continue",
        project_dir=project_dir,
        session_id=session_id,
        action=action,
        story_id=story_id,
        continuation=n,
    )
    return {
        "continue": True,
        "reason": reason,
        "stop_reason": "",
        "activity": {
            "kind": "loop_continue",
            "summary": f"continuation {n}: {action} for {story_id}",
        },
    }


def main() -> int:
    """CLI surface for the shell hook.

    Usage: loop_engine.py <project_dir> <session_id>
    Prints a JSON line with the decision. Exit 0 always (a broken loop engine
    must never block the session from stopping)."""
    import json
    import sys

    if len(sys.argv) < 2:
        print("{}")
        return 0
    project_dir = sys.argv[1]
    session_id = sys.argv[2] if len(sys.argv) > 2 else ""
    try:
        print(json.dumps(should_continue(project_dir, session_id)))
    except Exception as exc:  # never let the engine break the Stop hook
        print(json.dumps({"continue": False, "stop_reason": f"engine_error:{exc}"}))
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
